  private var appConfiguration: AppConfiguration = AppConfiguration()
  private lateinit var webView: WebView
  private var isFirstStep: Boolean = true
  private var inSetterSolverMode: Boolean = true
  private var taskSamplingDone: Boolean = false
  private var periodicExtrasLogger: PeriodicExtrasLogger = PeriodicExtrasLogger(this, 100)
  internal var shouldPeriodicallyLogExtras: Boolean = false
  internal var isPaused: Boolean = false
  private var episodeReward: String = ""
  private lateinit var rewardReceiver: RewardBroadcastReceiver
  private var episodeUtterance: String = ""
  private lateinit var taskInfoReceiver: RewardBroadcastReceiver

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)

    taskInfoReceiver = RewardBroadcastReceiver()
    requestWindowFeature(Window.FEATURE_NO_TITLE)
    setContentView(R.layout.activity_main)

    webView = findViewById(R.id.webView)
    webView.settings.javaScriptEnabled = true
    webView.settings.domStorageEnabled = true // Allows window.localStorage
    webView.setInitialScale(500)

    webView.webChromeClient =
      object : WebChromeClient() {
        override fun onConsoleMessage(consoleMessage: ConsoleMessage): Boolean {
          var message = consoleMessage.message()
          if (message.startsWith("reward")) {
            // The expected message is of the form "reward: 0.5292310719 (raw: 0.690902182)"
            // We want the raw (undiscounted) reward.
            setEpisodeReward(message.split(" ")[3].dropLast(1).toString())
            logger.i(TAG, "reward: " + getEpisodeReward())
            logger.i(TAG, "episode_end")
          } else if (message.startsWith("utterance")) {
            setEpisodeUtterance(message.split("utterance: ")[1])
          } else {
            logger.d(TAG, message)
          }
          return true
        }
      }
    webView.webViewClient =
      object : WebViewClient() {
        override fun onPageFinished(view: WebView, url: String) {
          if (inSetterSolverMode && url == INDEX_PATH && !taskSamplingDone) {
            // We sample 10 tasks and then trigger the function that draws the table of tasks.
            webView.loadUrl(
              """javascript:
tasks.selectTasksForEpisode(10, /*excludedTasks=*/BROKEN_ANDROID_TASKS);
window.onload();
"""
            )
            taskSamplingDone = true
            logger.i(TAG, "Tasks selected.")
          }
          super.onPageFinished(view, url)
        }

        override fun shouldOverrideUrlLoading(
          view: WebView?,
          request: WebResourceRequest?,
        ): Boolean {
          logger.i(TAG, "shouldOverrideUrlLoading")
          val url = request?.url.toString()
          view?.loadUrl(url)
          return super.shouldOverrideUrlLoading(view, request)
        }
      }
    appConfiguration = AppConfiguration.fromIntent(intent) ?: return
    loadTask()
  }

  override fun onPause() {
    isPaused = true
    super.onPause()
    unregisterReceiver(taskInfoReceiver)
  }

  // This is for a research environment, running on emulators. We need to query this using adb
  // hence it is cross-app and cross-process.
  @SuppressLint("UnprotectedReceiver")
  override fun onResume() {
    isPaused = false
    super.onResume()
    val filter =
      IntentFilter().apply {
        addAction(GET_REWARD_ACTION)
        addAction(GET_UTTERANCE_ACTION)
      }
    registerReceiver(taskInfoReceiver, filter)
  }

  override fun onBackPressed() {
    if (inSetterSolverMode && webView.canGoBack()) {
      webView.goBack()
    }
  }

  override fun onNewIntent(intent: Intent?) {
    super.onNewIntent(intent)
    intent ?: return
    val extras: Bundle? = intent.getExtras()
    extras ?: return
    for (key: String in extras.keySet()) {
      when (key) {
        "reset" -> reset()
        "step" -> step()
        "RL_TASK_APP_CONFIG" -> {
          appConfiguration = AppConfiguration.fromIntent(intent) ?: return
          for (bundleKey in extras.keySet()) {
            val value = extras.getString(bundleKey)
            logger.i(TAG, "Intent bundle: key='$bundleKey', value='$value'")
          }
          loadTask()
        }
        else -> logger.w(TAG, "Ignoring intent extra: " + key)
      }
    }
  }

  // This method is expected to be called once the reset_steps are finished, and only in
  // task mode ([!inSetterSolverMode]).
  private fun reset() {
    // Skip start screen and pause timers.
    webView.loadUrl(
      """javascript:
core.startEpisodeReal();
clearTimeout(core.EP_TIMER);
clearInterval(core.CD_TIMER);
core.EP_TIMER = null;
core.CD_TIMER = null;
core.hideDisplay();
"""
    )
    logExtras()
    isFirstStep = true
    setEpisodeReward("")
    setEpisodeUtterance("")
  }

  // This method is expected to be called on the first step, and only in
  // task mode ([!inSetterSolverMode]).
  private fun step() {
    if (isFirstStep) {
      isFirstStep = false
      shouldPeriodicallyLogExtras = true
    }
  }

  internal fun logExtras() {
    webView.loadUrl(
      """javascript:
console.log("extra: utterance '" + core.getUtterance() + "'");
console.log("extra: task_name '" + document.URL.substring(document.URL.lastIndexOf('/') + 1).replace(/\.html.*/, '') + "'");
console.log("extra: timer " + $GET_TIMERS);
"""
    )
  }

  // This method is expected to be called at every reset, before the [reset] intent.
  fun loadTask() {
    shouldPeriodicallyLogExtras = false
    val taskName: String = appConfiguration.get("task", DEFAULT_TASK)
    logger.d(TAG, "taskName: " + taskName)
    val path: String
    if (taskName == "index") {
      path = INDEX_PATH
      inSetterSolverMode = true
      taskSamplingDone = false
    } else {
      path = "file:///android_asset/html/miniwob/" + taskName + ".html"
      inSetterSolverMode = false
    }
    webView.loadUrl(path)
  }

  inner class RewardBroadcastReceiver : BroadcastReceiver() {
    // Expose reward, so it can be queried with adb.
    override fun onReceive(context: Context, intent: Intent) {
      if (intent.action == GET_REWARD_ACTION) {
        setResultCode(Activity.RESULT_OK)
        setResultData(getEpisodeReward())
      }
      if (intent.action == GET_UTTERANCE_ACTION) {
        setResultCode(Activity.RESULT_OK)
        setResultData(getEpisodeUtterance())
      }
    }
  }

  fun setEpisodeReward(rewardValue: String) {
    episodeReward = rewardValue
  }

  fun getEpisodeReward(): String {
    return episodeReward
  }

  fun setEpisodeUtterance(utteranceValue: String) {
    episodeUtterance = utteranceValue
  }

  fun getEpisodeUtterance(): String {
    return episodeUtterance
  }

  fun getWebView(): WebView {
    return webView
  }
}

/*
Utilities for generating and describing shapes/digits/letters in a grid
that have various properties.
*/

var shapes = {};

// env variables
shapes.SZ_X = 7; // number of bins for shapes
shapes.SZ_Y = 7;
shapes.MAX_SIZE = 20; // max render size of shapes in pixels. Note by default grid is 160x160, so 8*20=160.

shapes.MAX_NUM_SHAPES = 20;
shapes.MIN_NUM_SHAPES = 3;
shapes.COLORS = ['red', 'green', 'blue', 'aqua', 'black', 'magenta', 'yellow'];
shapes.LETTERS = 'qwertyuiopasdfghjklzxcvbnmQWERTYUIOPASDFGHJKLZXCVBNM';
shapes.DIGITS = '1234567890';
shapes.SHAPES = ['circle', 'rectangle', 'triangle'];

// helper function that creates a grid of shapes
shapes.genGrid = function(n) {

  var grid = {};
  grid.shapes = [];

  var taken_positions = [];
  var num_shapes = typeof n !== 'undefined' ? n : core.randi(shapes.MIN_NUM_SHAPES, shapes.MAX_NUM_SHAPES);
  for(var i=0;i<num_shapes;i++) {

    // generate properties of a shape
    while(true) {
      var x = core.randi(0, shapes.SZ_X);
      var y = core.randi(0, shapes.SZ_Y);
      var xystr = x + ',' + y;
      if(!taken_positions.hasOwnProperty(xystr)) { // make sure it's not taken yet
        taken_positions[xystr] = 1;
        break;
      }
    }
    var color = shapes.COLORS[core.randi(0, shapes.COLORS.length)];
    var size = core.randf(0,1) < 0.5 ? 1 : 0;

    // a letter, digit or a shape
    var r = core.randf(0,1);
    if(r < 0.5) {
      var type = 'letter';
      var text = shapes.LETTERS[core.randi(0, shapes.LETTERS.length)];
    } else if(r < 0.7) {
      var type = 'digit';
      var text = shapes.DIGITS[core.randi(0, shapes.DIGITS.length)];
    } else {
      var type = 'shape';
      var text = shapes.SHAPES[core.randi(0, shapes.SHAPES.length)];
    }

    var shape = {x:x, y:y, color:color, size:size, type:type, text:text}
    grid.shapes.push(shape)
  }

  return grid;
}

// renders the grid into svg and modifies grid in place with pointers to the added elements.
shapes.renderGrid = function(svg, grid) {

  svg.html(''); // clear previous problem, if any
  grid.svg = svg; // save the element to grid object

  // // draw grid (used in debugging)
  // var drawGrid = function() {
  //   for(var x=0;x<shapes.SZ_X;x++) {
  //     for(var y=0;y<shapes.SZ_Y;y++) {
  //       var svg_shape = svg.append('circle')
  //         .attr('cx', x*shapes.MAX_SIZE + shapes.MAX_SIZE/2)
  //         .attr('cy', y*shapes.MAX_SIZE + shapes.MAX_SIZE/2)
  //         .attr('r', shapes.MAX_SIZE/2)
  //         .attr('fill', '#FFF')
  //         .attr('stroke', '#000');
  //     }
  //   }
  // }
  // drawGrid();

  var shapesToRender = grid.shapes;
  for(var i=0, n=shapesToRender.length; i<n; i++) {
    var s = shapesToRender[i]; // shape
    var xcoord = s.x*shapes.MAX_SIZE + shapes.MAX_SIZE/2; // of center
    var ycoord = s.y*shapes.MAX_SIZE + shapes.MAX_SIZE/2;
    var szcoord = Math.ceil(shapes.MAX_SIZE/2*s.size)+shapes.MAX_SIZE/2;

    if(s.type === 'letter' || s.type === 'digit') {
      var svg_shape = svg.append('text')
        .attr('x', xcoord)
        .attr('y', ycoord)
        .attr('fill', s.color)
        .attr('text-anchor', 'middle')
        .attr('alignment-baseline', 'central')
        .attr('font-size', szcoord + 'px')
        .text(s.text);
    }
    if(s.type === 'shape') {
      if(s.text === 'rectangle') {
        var svg_shape = svg.append('rect')
        .attr('x', xcoord-szcoord/2)
        .attr('y', ycoord-szcoord/2)
        .attr('width', szcoord)
        .attr('height', szcoord)
        .attr('fill', s.color);
      }
      if(s.text === 'circle') {
        var svg_shape = svg.append('circle')
          .attr('cx', xcoord)
          .attr('cy', ycoord)
          .attr('r', szcoord/2)
          .attr('fill', s.color);
      }
      if(s.text === 'triangle') {
        var points = (xcoord - szcoord/2) + ',' + (ycoord + szcoord/2) + ' '
                    +(xcoord) + ',' + (ycoord - szcoord/2) + ' '
                    +(xcoord + szcoord/2) + ',' + (ycoord + szcoord/2);
        var svg_shape = svg.append('polygon')
          .attr('points', points)
          .attr('fill', s.color);
      }
    }

    svg_shape.attr('style', 'cursor:pointer;'); // make hand pointer
    s.svg_shape = svg_shape; // modify grid in place, attach the actual SVG element to the dict
  }
}

shapes.generalDesc = function(s) {
  // given a shape, describe it in text in a lossy way (ignoring some attributes at random)
  var text = '';
  var sztxt = core.randf(0,1) < 0.5 ? ((s.size == 1 ? 'large' : 'small')) : '';
  if(sztxt !== '') { text += sztxt + ' '; }
  var coltxt = core.randf(0,1) < 0.5 ? s.color : '';
  if(coltxt !== '') { text += coltxt + ' '; }
  if(core.randf(0,1) < 0.5 || (sztxt === '' && coltxt === '')) {
    if(core.randf(0,1) < 0.5) {
      var stxt = s.text; // reveal full details
    } else {
      var stxt = s.type; // reveal only type (e.g. shape/digit/letter)
    }
  } else {
    var stxt = 'item'; // reveal nothing
  }
  text += stxt;
  return {text: text, parts:[sztxt, coltxt, stxt]};
}

shapes.sampleDesc = function() {
  // sample a random possible description
  var g = shapes.genGrid(1);
  var desc = shapes.generalDesc(g.shapes[0]);
  return desc;
}

shapes.shapeMatchesText = function(s, desc) {
  // verifies that a shape matches some description
  var szmatch = desc.parts[0] === '' || ((s.size == 1 ? 'large' : 'small') === desc.parts[0]);
  var colmatch = desc.parts[1] === '' || (s.color === desc.parts[1]);
  var smatch = desc.parts[2] === 'item' || (s.text === desc.parts[2] || s.type === desc.parts[2]); // fine for now. technically we're mixing up type/text
  return szmatch && colmatch && smatch;
}

// function to define dragging a shape around a grid
shapes.drag = d3.behavior.drag()
  .on('drag', function(){
    var dim = this.getBBox().width;
    var shapeType = this.tagName;
    var shift_x = d3.event.x - this.getBBox().x;
    var shift_y = d3.event.y - this.getBBox().y;

    if(shapeType==='rect') {
      shift_x -= dim*0.5;
      shift_y -= dim*0.5;
    } else if(shapeType==='circle') {
      shift_x -= dim*0.6;
      shift_y -= dim*0.6;
    } else if(shapeType==='polygon') {
      shift_x -= dim*0.4;
      shift_y -=  dim*0.4;
    }

    d3.select(this)
      .attr("transform", "translate(" + shift_x + "," + shift_y + ")");
});

// determine coordinates of a shape within a grid
shapes.gridCoords = function(shape){
  var shapeType = shape.tagName;
  var coords = {};
  coords.x = shape.getBBox().x;
  coords.y = shape.getBBox().y;

  if(shape.getAttribute('transform') === null) return coords;
  else var shift = shape.getAttribute('transform').replace(/[^0-9\,\-\.]+/g, '').split(",")

  coords.x += parseFloat(shift[0],10);
  coords.y += parseFloat(shift[1],10);

  return coords;
}

// draw circles on a given grid.
shapes.drawCircles = function(circles, grid){
  for(var i=0;i<circles.length;i++){
    var circle = circles[i];
    grid
      .append('circle')
      .attr('class', circle.class)
      .attr('id', circle.id)
      .attr('cx', circle.cx)
      .attr('cy', circle.cy)
      .attr('r', circle.r)
      .attr('stroke', circle.stroke ? circle.stroke : '')
      .attr('fill', circle.fill ? circle.fill : 'black');
  }
}

// draw lines on a given grid.
shapes.drawLines = function(lines, grid){
  for(var i=0;i<lines.length;i++){
    var line = lines[i];
    grid.append('line')
      .style('stroke', line.stroke ? line.stroke : 'black')
      .attr('class', line.class)
      .attr('x1', line.x1)
      .attr('x2', line.x2)
      .attr('y1', line.y1)
      .attr('y2', line.y2)
  }
}
